inline const SKR *GetSKR(const void *buf) {
  return ::flatbuffers::GetRoot<SKR>(buf);
}

inline const SKR *GetSizePrefixedSKR(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SKR>(buf);
}

inline const char *SKRIdentifier() {
  return "$SKR";
}

inline bool SKRBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SKRIdentifier());
}

inline bool SizePrefixedSKRBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SKRIdentifier(), true);
}

template <bool B = false>
inline bool VerifySKRBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SKR>(SKRIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSKRBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SKR>(SKRIdentifier());
}

inline void FinishSKRBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SKR> root) {
  fbb.Finish(root, SKRIdentifier());
}

inline void FinishSizePrefixedSKRBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SKR> root) {
  fbb.FinishSizePrefixed(root, SKRIdentifier());
}

